// The web configurator. Three speeds:
//   1. rules (@draftwork/rules) run here on every change: form, checks, price and parts list update at once;
//   2. the 3D preview rebuilds the real model in a Web Worker (@draftwork/core) a moment later;
//   3. release files are generated by the server (POST /api/products/:id/jobs) and cached there.
import { compile, display } from '/rules/index.mjs';
import { createViewer } from '/viewer.mjs';

const $ = s => document.querySelector(s);
const el = (tag, attrs = {}, ...kids) => {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (v == null || v === false) continue;
    if (k.startsWith('on')) e.addEventListener(k.slice(2), v); else if (k === 'class') e.className = v; else e.setAttribute(k, v === true ? '' : v);
  }
  for (const c of kids.flat()) if (c != null && c !== false) e.append(c.nodeType ? c : document.createTextNode(c));
  return e;
};

let product = null, project = null, answers = {}, result = null, seq = 0, shown = 0, worker = null, ready = false, viewer = null, pollTimer = null;

async function getJSON(url, opts) {
  const r = await fetch(url, opts);
  const body = await r.json().catch(() => ({}));
  if (!r.ok) { const e = new Error(body.error || r.statusText); e.details = body.details; e.status = r.status; throw e; }
  return body;
}

async function start() {
  viewer = createViewer($('#view'));
  $('#fit').addEventListener('click', () => viewer.fit());
  $('#reset').addEventListener('click', () => { answers = {}; update(); });
  $('#share').addEventListener('click', share);
  $('#generate').addEventListener('click', generate);
  const list = await getJSON('/api/products');
  const usable = list.filter(p => p.ok);
  if (!usable.length) { $('#subtitle').textContent = 'No products are available yet.'; return; }
  const params = new URLSearchParams(location.search);
  const id = usable.some(p => p.id === params.get('product')) ? params.get('product') : usable[0].id;
  if (usable.length > 1) {
    $('#pickerWrap').hidden = false;
    $('#picker').replaceChildren(...usable.map(p => el('option', { value: p.id, selected: p.id === id }, p.title)));
    $('#picker').addEventListener('change', e => { location.search = '?product=' + encodeURIComponent(e.target.value); });
  }
  try { answers = JSON.parse(params.get('a') || '{}'); } catch (e) { answers = {}; }
  await load(id);
}

async function load(id) {
  product = await getJSON('/api/products/' + encodeURIComponent(id));
  project = compile(product.config);
  document.title = product.title + ' · Configurator';
  $('#title').textContent = product.title;
  $('#subtitle').textContent = 'Choose the options; the price and the 3D model follow.';
  worker = new Worker('/preview-worker.mjs', { type: 'module' });
  worker.onmessage = ({ data }) => {
    if (data.type === 'ready') { ready = true; setView('Building the 3D model…'); build(); }
    else if (data.type === 'failed') setView('3D preview unavailable: ' + data.message);
    else if (data.type === 'built' && data.seq >= shown) {
      shown = data.seq;
      if (data.ok) { viewer.show(data.meshes); setView(`3D model · ${data.size ? data.size.map(v => +v.toFixed(1)).join(' × ') + ' mm · ' : ''}rebuilt in ${data.ms < 1000 ? data.ms + ' ms' : (data.ms / 1000).toFixed(1) + ' s'}`); }
      else setView('The model could not be built for these options: ' + (data.errors?.[0]?.message || 'unknown error'));
      $('#view').dataset.seq = String(data.seq);
    }
  };
  worker.postMessage({ type: 'init', design: product.design });
  update();
}

const setView = t => { $('#viewStatus').textContent = t; };

function update() {
  result = project.evaluate(answers);
  renderForm();
  renderSummary();
  history.replaceState(null, '', '?' + new URLSearchParams({ product: product.id, ...(Object.keys(answers).length ? { a: JSON.stringify(answers) } : {}) }));
  clearTimeout(update.t);
  update.t = setTimeout(build, 120);
  resetJob();
}

function build() {
  if (!worker || !ready || !result) return;   // the first build happens when the engine is ready
  if (!result.ok) { setView('Fix the highlighted options to update the model.'); return; }
  seq += 1;
  worker.postMessage({ type: 'build', seq, params: result.model.params, suppressed: result.model.suppressed });
  if (shown) setView('Updating the 3D model…');
}

function answer(name, value) { answers = { ...answers, [name]: value }; update(); }

function renderForm() {
  const errsFor = name => result.messages.filter(m => m.level === 'error' && m.source.kind === 'input' && m.source.name === name);
  const out = [];
  let group = null;
  for (const f of result.form) {
    if (f.visible === false) continue;
    if (f.group && f.group !== group) { group = f.group; out.push(el('h3', { class: 'group' }, group)); }
    const id = 'f-' + f.name, errs = errsFor(f.name), unit = f.unit ? ' ' + f.unit : '';
    let control;
    if (f.type === 'boolean') {
      control = el('label', { class: 'toggle' }, el('input', { type: 'checkbox', id, checked: !!f.value, onchange: e => answer(f.name, e.target.checked) }), f.value ? 'Yes' : 'No');
    } else if (f.type === 'choice' && (f.options || []).length <= 5) {
      control = el('div', { class: 'chips', role: 'group', 'aria-label': f.label },
        ...f.options.map(o => el('button', { type: 'button', 'aria-pressed': String(display(o) === display(f.value)), onclick: () => answer(f.name, o) }, display(o) + unit)));
    } else if (f.type === 'choice') {
      control = el('select', { id, onchange: e => answer(f.name, f.options[e.target.selectedIndex]) }, ...f.options.map(o => el('option', { selected: display(o) === display(f.value) }, display(o) + unit)));
    } else {
      control = el('input', { id, value: f.value ?? '', inputmode: f.type === 'number' ? 'decimal' : null, 'aria-invalid': errs.length ? 'true' : null, onchange: e => answer(f.name, e.target.value.trim()) });
    }
    const hint = f.type === 'number' && (f.min != null || f.max != null) ? `${f.min ?? ''} to ${f.max ?? ''}${unit}` : f.help || '';
    out.push(el('div', { class: 'field' + (errs.length ? ' bad' : '') },
      f.type === 'choice' && (f.options || []).length <= 5 ? el('span', { class: 'label', style: 'font-weight:600;font-size:13px' }, f.label) : el('label', { for: id }, f.label),
      control, hint ? el('span', { class: 'hint' }, hint) : null, ...errs.map(m => el('span', { class: 'err' }, m.message.replace(/^[^:]+:\s*/, '')))));
  }
  $('#form').replaceChildren(...out);
}

function money(x) {
  const c = result.price.currency;
  const s = Math.abs(x).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return (x < 0 ? '−' : '') + (c ? c + ' ' : '') + s;
}

function renderSummary() {
  const general = result.messages.filter(m => !(m.level === 'error' && m.source.kind === 'input'));
  $('#messages').replaceChildren(...general.map(m => el('p', { class: 'msg ' + m.level }, m.message)));
  $('#partTitle').textContent = result.text.title || 'Your configuration';
  $('#partNumber').textContent = result.text.part_number || '';
  const rows = result.price.lines.map(l => el('tr', { class: l.amount < 0 ? 'discount' : '' }, el('td', {}, l.line), el('td', {}, money(l.amount))));
  if (result.price.lines.length) rows.push(el('tr', { class: 'total' }, el('td', {}, 'Total'), el('td', { id: 'total' }, money(result.price.total))));
  $('#price').replaceChildren(...rows);
  $('#bomWrap').hidden = !result.bom.length;
  $('#bom').replaceChildren(...result.bom.map(b => el('tr', {}, el('td', {}, b.item), el('td', { class: 'num' }, `${display(b.qty)} ${b.unit}`))));
  $('#generate').disabled = !result.ok;
}

function resetJob() { clearTimeout(pollTimer); $('#files').replaceChildren(); $('#jobStatus').textContent = ''; }

async function generate() {
  resetJob();
  $('#generate').disabled = true;
  $('#jobStatus').textContent = 'Sending your configuration…';
  try {
    let job = await getJSON(`/api/products/${encodeURIComponent(product.id)}/jobs`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ answers }) });
    const started = Date.now();
    const poll = async () => {
      if (job.status === 'done') return showFiles(job);
      if (job.status === 'failed') { $('#jobStatus').textContent = 'The files could not be made: ' + (job.error || 'unknown error'); $('#generate').disabled = false; return; }
      $('#jobStatus').textContent = (job.status === 'queued' ? 'Waiting for the generator…' : 'Making your drawings and CAD files…') + ` ${Math.round((Date.now() - started) / 1000)} s`;
      pollTimer = setTimeout(async () => { try { job = await getJSON('/api/jobs/' + job.id); } catch (e) { /* keep polling */ } poll(); }, 800);
    };
    poll();
  } catch (e) {
    $('#jobStatus').textContent = e.status === 422 ? e.message + ': ' + (e.details || []).map(d => d.message).join('; ') : 'Could not reach the generator: ' + e.message;
    $('#generate').disabled = !result.ok;
  }
}

function showFiles(job) {
  const label = n => n.endsWith('.step') ? 'STEP (CAD model)' : n.endsWith('.stl') ? 'STL (3D print / mesh)' : n.endsWith('-flat.dxf') ? 'DXF flat pattern' : /-(\w+)\.svg$/.test(n) ? `Drawing view: ${n.match(/-(\w+)\.svg$/)[1]}` : n;
  const size = b => b > 1e6 ? (b / 1e6).toFixed(1) + ' MB' : Math.max(1, Math.round(b / 1e3)) + ' KB';
  $('#files').replaceChildren(...job.files.map(f => el('li', {}, el('a', { href: f.url, download: f.name }, el('span', {}, label(f.name)), el('span', { class: 'size' }, size(f.size))))));
  $('#jobStatus').textContent = `Ready${job.cached ? ' (built before, served from the cache)' : ''}. Reference ${job.id.slice(0, 8)}.`;
  $('#generate').disabled = false;
}

async function share() {
  try { await navigator.clipboard.writeText(location.href); $('#share').textContent = 'Link copied'; }
  catch (e) { $('#share').textContent = 'Copy the address bar to share'; }
  setTimeout(() => { $('#share').textContent = 'Copy link to this configuration'; }, 2500);
}

start().catch(e => { $('#subtitle').textContent = 'The configurator could not start: ' + e.message; });
